def inr_format(n):
    if n < 1000:
        return str(n)
    s = str(n)
    result = []
    i = len(s)
    while i > 0:
        if i > 3:
            result.append(s[i-3:i])
            i -= 3
        else:
            result.append(s[:i])
            break
    return ','.join(reversed(result))

def inr_format(n):
    s = str(n)
    if len(s) <= 3:
        return s
    result = []
    # Add the last 3 digits
    result.append(s[-3:])
    # Process remaining digits in reverse, grouping by 2
    for i in range(len(s) - 4, -1, -2):
        result.append(s[i:i+2])
    # Reverse to get correct order
    return ','.join(reversed(result))

