def emi(P, annual_rate, n):
    if annual_rate == 0:
        return round(P / n, 2)
    monthly_rate = annual_rate / 100 / 12
    numerator = P * monthly_rate * (1 + monthly_rate) ** n
    denominator = (1 + monthly_rate) ** n - 1
    emi = numerator / denominator
    return round(emi, 2)

